from pathlib import Path
import sys
r=Path(sys.argv[1])
d=(r/'Dockerfile').read_text(encoding='utf-8')
req=(r/'requirements.txt').read_text(encoding='utf-8')
assert 'httpx==0.28.1' in req, 'requirements.txt: httpx pin missing'
assert 'websockets==15.0.1' in req, 'requirements.txt: websockets pin missing'
pip_marker='RUN pip install --no-cache-dir -r requirements.txt'
self_marker='python scripts/selfcheck.py'
assert pip_marker in d, 'Dockerfile: requirements install missing'
assert self_marker in d, 'Dockerfile: selfcheck missing'
assert d.index(pip_marker) < d.index(self_marker), 'Dockerfile: selfcheck runs before dependencies'
print('DEPENDENCY_ORDER=PASS selfcheck_after_pip_install')
main=(r/'app/main.py').read_text(encoding='utf-8')
assert 'WS_REG_ITEM_BUDGET' in main and 'SESSION_AWARE_HARD_CAP' in main, 'WS budget guard missing'
assert 'STABLE_LIVE_BOARD_WS_ADMISSION_HYSTERESIS' in main and 'def stable_live_board' in main, 'stable live board guard missing'
