assert 'LIVE_BOARD_MIN_HOLD_SECONDS' in main and 'LIVE_BOARD_STALE_GRACE_SECONDS' in main, 'live board hysteresis constants missing'
assert 'def _prebuy_recommendation_row' in main and 'PRE_SURGE_BUY_RECOMMENDATION' in main, 'pre-surge BUY recommendation missing'
