import json,sys
from pathlib import Path
r=Path(sys.argv[1]); m=(r/'app/main.py').read_text(encoding='utf-8'); b=json.loads((r/'BUILD_INFO.json').read_text(encoding='utf-8'))
checks = [
    ('APP_VERSION', "APP_VERSION='NOVA-2.4.22'" in m),
    ('WS_TYPES_0B_0u_0D', "'trade_type':'0B','program_type':'0u','orderbook_type':'0D'" in m),
    ('WS_TRADE_NOT_0A', "'trade_type':'0A'" not in m and "'trade':'0A'" not in m),
    ('PROGRAM_API_KA90003_ONLY', 'ka90003' in m and 'ka90004' not in m),
    ('VENUE_TRUTH_FUNCTION', 'def venue_from_realtime_item' in m),
    ('PROGRAM_SOURCE_0u', "source='0u'" in m),
    ('ORDERBOOK_FID_RANGES', "range(41,51)" in m and "range(61,71)" in m),
    ('ORDERBOOK_FULL_DEPTH_0D', "'orderbook_type':'0D'" in m and '0C=stock best quote' in b.get('orderbook_contract_audit','')),
    ('STABLE_LIVE_BOARD', 'STABLE_LIVE_BOARD_WS_ADMISSION_HYSTERESIS' in m and 'stable_live_board' in m),
    ('UNIT_SAFE_SESSION_VWAP', 'normalized_session_vwap' in m and 'session_vwap_policy' in b),
    ('BUILD_VERSION', b.get('version')=='NOVA-2.4.22'),
    ('BUILD_LIVE_CONTRACT', '0B/0u/0D' in b.get('live_contract','')),
    ('BUILD_KRX_BACKFILL', 'ka90003' in b.get('krx_close_backfill','')),
    ('BUY_POLICY_FROZEN', 'FROZEN_FROM_2.4.8' in b.get('buy_policy','')),
    ('NXT_DISPLAY_POLICY', 'DISPLAY_ONLY_CONSERVATIVE' in b.get('nxt_signal_management','')),
    ('ALERT_TOGGLE_POLICY', 'USER_CONTROLLED_V2' in b.get('alert_toggle','')),
    ('RS_LEADER_TABLE', b.get('rs_leader_table','').startswith('V2 TOP10 display-only')),
    ('PRE_SURGE_BUY_PRIMARY', 'def _prebuy_recommendation_row' in m and 'PRE_SURGE_BUY_RECOMMENDATION' in m),
    ('CLOSE_PREVIEW', 'def _close_preview_rows' in m and '19:30 공식선정 전 실시간 PREVIEW' in m),
    ('BUILD_PREBUY', (lambda x: all(tok in x for tok in ('primary','pre-surge','buy_early','buy_ready')))(b.get('buy_recommendation','').lower())),
    ('WS_SELF_HEAL', 'ACTIVE_FAST_RECONNECT_MAX3S' in b.get('ws_registry','') and 'NO_MESSAGE_WATCHDOG' in b.get('ws_registry','')),
    ('RECONNECT_BOARD_HOLD', 'active reconnect retains last board' in b.get('ui_live_board','')),
    ('R12_PRIMARY_RENDER', "@app.get('/api/prebuy-recommendations')" in m),
]
failed=[name for name,ok in checks if not ok]
for name,ok in checks:
    print(f'STATIC_CHECK {name}={"PASS" if ok else "FAIL"}')
if failed:
    raise SystemExit('STATIC_CONTRACT_FAILED: ' + ','.join(failed))
assert 'PREBUY_MIN_HOLD_SECONDS' in m and 'def _raw_prebuy_recommendations' in m and 'display_status' in m
html=(r/'static/index.html').read_text(encoding='utf-8'); js=(r/'static/nova.js').read_text(encoding='utf-8')
