      LINE="$(python3 - "$TMP/live.json" "$LIVE_GATE_START_EPOCH" <<'PYLIVE'
import sys,json
h=json.load(open(sys.argv[1])); start=float(sys.argv[2]); w=h.get('ws') or {}; f=h.get('feed') or {}; ct=h.get('ws_contract') or {}
connected=bool(w.get('connected')); tr=int(w.get('trade_registered') or 0); lt=float(w.get('last_trade_at') or 0); ack=int(w.get('ack') or 0)
prog=int(w.get('program_registered') or 0); ob=int(w.get('orderbook_registered') or 0)
