contract=(ct.get('trade_type'),ct.get('program_type'),ct.get('orderbook_type'))
aux_ok=(pt==0 or prog>0) and (ot==0 or ob>0) and not w.get('program_reg_error') and not w.get('orderbook_reg_error')
ok=connected and tr>0 and lt>=start-5 and contract==('0B','0u','0D') and f.get('state')!='DISCONNECTED' and aux_ok
print(('PASS' if ok else 'WAIT')+f" connected={connected} trade_reg={tr} krx={int(w.get('krx_registered') or 0)} nxt={int(w.get('nxt_registered') or 0)} program={prog}/{pt} orderbook={ob}/{ot} ack={ack} feed={f.get('state')} last_trade={lt:.3f} program_error={str(w.get('program_reg_error') or '')[:60]} orderbook_error={str(w.get('orderbook_reg_error') or '')[:60]} last_error={str(w.get('last_error') or '')[:80]}")
PYLIVE
)"
